import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"晚秋天","description":"","frontmatter":{"title":"晚秋天","date":"2026-11-20T00:00:00.000Z","seq":116,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词","prev":{"text":"一声画角日西曛","link":"/blogs/全宋词·柳永/一声画角日西曛.html"},"next":{"text":"一枕清宵好梦","link":"/blogs/全宋词·柳永/一枕清宵好梦.html"}},"headers":[],"relativePath":"blogs/全宋词·柳永/晚秋天.md","filePath":"blogs/全宋词·柳永/晚秋天.md"}'),o={name:"blogs/全宋词·柳永/晚秋天.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="晚秋天" tabindex="-1">晚秋天 <a class="header-anchor" href="#晚秋天" aria-label="Permalink to &quot;晚秋天&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　戚氏</p><div class="poem"><p class="poem-stanza">晚秋天。</p><p class="poem-stanza">一霎微雨洒庭轩。</p><p class="poem-stanza">槛菊萧疏，井梧零乱惹残烟。</p><p class="poem-stanza">凄然。</p><p class="poem-stanza">望江关。</p><p class="poem-stanza">飞云黯淡夕阳间。</p><p class="poem-stanza">当时宋玉悲感，向此临水与登山。</p><p class="poem-stanza">远道迢递，行人凄楚，倦听陇水潺湲。</p><p class="poem-stanza">正蝉吟败叶，蛩响衰草，相应喧喧。</p><p class="poem-stanza">孤馆度日如年。</p><p class="poem-stanza">风露渐变，悄悄至更阑。</p><p class="poem-stanza">长天净，绛河清浅，皓月婵娟。</p><p class="poem-stanza">思绵绵。</p><p class="poem-stanza">夜永对景，那堪屈指，暗想从前。</p><p class="poem-stanza">未名未禄，绮陌红楼，往往经岁迁延。</p><p class="poem-stanza">帝里风光好，当年少日，暮宴朝欢。</p><p class="poem-stanza">况有狂朋怪侣，遇当歌、对酒竞留连。</p><p class="poem-stanza">别来迅景如梭，旧游似梦，烟水程何限。</p><p class="poem-stanza">念利名、憔悴长萦绊。</p><p class="poem-stanza">追往事、空惨愁颜。</p><p class="poem-stanza">漏箭移、稍觉轻寒。</p><p class="poem-stanza">渐呜咽、画角数声残。</p><p class="poem-stanza">对闲窗畔，停灯向晓，抱影无眠。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
